-- Vashj'ir spawns, part 6 of 6: the rows of this part are deleted by key range before they are inserted, so the file can run twice.
-- Based on Legends of Azeroth 5.4.8 and The Cataclysm Preservation Project 4.3.4.

DELETE FROM `waypoint_data` WHERE (`id` > 92645620 OR (`id` = 92645620 AND `point` >= 2)) AND (`id` < 92648200 OR (`id` = 92648200 AND `point` <= 12));
DELETE FROM `gameobject` WHERE `guid` BETWEEN 1063000 AND 1063136;
DELETE FROM `pool_template` WHERE `entry` BETWEEN 330000 AND 330001;
DELETE FROM `pool_creature` WHERE `guid` BETWEEN 9264550 AND 9264829;





